data.getWeaponBaseDmg:
function getWeaponBaseDmg(key) {
        const cat = WEAPON_CATALOG[key];
        if (!cat) return '未知';
        if (key === 'thunderblade') return `轻击${_adjBase('thunderblade', cat.baseDmgLight)} / 重击${_adjBase('thunderblade', cat.baseDmgHeavy)}`;
        if (key === 'normalgrenade') return `${_adjBase('normalgrenade', cat.baseDmg)}(爆炸)+DPS${_adjBase('normalgrenade', GRENADE_BURN_BASE_DPS)}(灼烧3s)`;
        if (key === 'deathlight') return `爆炸${_adjBase('deathlight', cat.baseDmg)} + 10x${_adjBase('deathlight', cat.baseDmgRocket)}火箭`;
        if (key === 'froststar') return `首爆${_adjBase('froststar', cat.baseDmgFirst)} + 二段${_adjBase('froststar', cat.baseDmgSecond)}`;
        if (key === 'tanglotus') return `爆炸${_adjBase('tanglotus', cat.baseDmg)} + ${cat.petalCount}x${_adjBase('tanglotus', cat.petalDmg)}花瓣`;
        if (key === 'genesislight') return `爆炸${_adjBase('genesislight', cat.baseDmg)}+致盲+解构领域`;
        if (key === 'luowang') return `蛛网DPS${_adjBase('luowang', cat.baseDmg)}+减速${Math.round(LUOWANG_WEB_SLOW*100)}%+眩晕`;
        if (key === 'fate') return `爆炸${_adjBase('fate', cat.baseDmg)}+命运领域(闪光致盲)`;
        if (key === 'hellscythe') return `轻风${_adjBase('hellscythe', cat.baseDmg)}/次 x10 | 地狱${_adjBase('hellscythe', cat.baseDmg)}/次 x10x3`;
        if (key === 'sharkblade') return `链锯${_adjBase('sharkblade', cat.baseDmg)}/跳 x10 | 重击${_adjBase('sharkblade', SHARK_HEAVY_DMG)} | 漩涡${_adjBase('sharkblade', SHARK_VORTEX_DMG)}`;
        if (key === 'datacube') return '无';
        if (key === 'starcore') return '星弹'+_adjBase('starcore', STARCORE_BULLET_DMG)+'/发 x2 | 星环增幅最高+200%';
        if (key === 'juexian') return '弦矢'+_adjBase('juexian', JUEXIAN_BULLET_DMG)+'/发 x2.5 | 弦韵共鸣最高+180% | 毁灭形态额外+75%';
        if (key === 'yanmo') return '炎魔火箭'+_adjBase('yanmo', YANMO_ROCKET_DMG)+'/发 x2.5 | 磁能增幅最高+220% | 炎魔领域磁缚定身+灼烧';
        if (key === 'chronoterminus') return '时序飞刃'+_adjBase('chronoterminus', CHRONO_BLADE_DMG)+'/发(穿透) | 时序增幅最高+280% | 时停领域移速+70%/免控/减伤55% | 命中减速50%';
        if (key === 'nullsingularity') return '相位弹'+_adjBase('nullsingularity', NS_BASE_DMG)+'/发 | 层数易伤最高+60% | 奇点坍缩牵引+减速70% | 虚数行走传送15m';
        if (key === 'terminus') return '暗能'+_adjBase('terminus', cat.baseDmg)+'/发(贯穿) | 横行无忌DPS≈'+Math.round(_adjBase('terminus', TERMINUS_BASE_DMG)*TERMINUS_RAMPAGE_DMG_PERCENT/100*TERMINUS_RAMPAGE_FREQ)+' | 双子之影自动攻击';
        if (key === 'thunderex') return '等离子'+_adjBase('thunderex', cat.baseDmg)+'/发(贯穿) | 雷切处决 | 圣化领域治疗+护盾 | 闪电链+电浆球';
        if (key === 'tianfa') return '雷霆'+_adjBase('tianfa', cat.baseDmg)+'/发(落雷) | 诺法雷落雷1000%系数 | 神之注视+25% | 神裁领域全场落雷+治疗护盾 | 压缩弹500%系数';
        if (key === 'tianshen') return '冰律'+_adjBase('tianshen', cat.baseDmg)+'/发(天神雷) | 钛合金铸体无视距离 | 天神雷35% | 势能爆珠弹射 | 冰封力场减速冰冻';
        if (key === 'ponghong') return '聚能射线'+_adjBase('ponghong', PONGHONG_BASE_DMG)+'/发 x30 | 怒火固定10条集火 | 耦合爆炸'+(pongHongWrathActive?PONGHONG_WRATH_COEF:PONGHONG_PASSIVE_COEF)+'00%系数';
        if (key === 'energydefender') return '能量'+_adjBase('energydefender', cat.baseDmg)+'/发(贯穿) | 穿敌+40%/个 | 屏蔽领域隔绝敌人+透过护盾伤害+50%';
        if (key === 'duel') return '金弹'+_adjBase('duel', cat.baseDmg)+'/发 | 毁灭射击连射×'+DUEL_DEVASTATE_MAX+'递增+'+Math.round(DUEL_DEVASTATE_INC*100)+'%/发 | 致命磁能叠层+'+Math.round(DUEL_MAGNETIC_MAX*100)+'% | 死眼低血处决 | 后台自动装填';
        if (key === 'guangling') return `音波${_adjBase('guangling', GUANGLING_WAVE_DMG)}/击 | 环音${_adjBase('guangling', GUANGLING_RING_DMG)} | 剑气斩${_adjBase('guangling', GUANGLING_SLASH_DMG)} | 剑气爆${_adjBase('guangling', GUANGLING_BURST_DMG)}`;
        if (key === 'thor') return '轻击'+_adjBase('thor', cat.baseDmgLight)+'/击 | 唤雷电圈持续伤害+雷印落雷 | 雷神降临信标爆炸+次级电圈 | 雷神之怒(近战吸血+减伤)';
        if (key === 'prism') return '折射弹'+_adjBase('prism', PRISM_BASE_DMG)+'/发(直击) · 每次反弹 ×'+PRISM_BOUNCE_MULT+'(上限'+PRISM_BOUNCE_MAX+'次) | 聚光同目标每次+45% | ≥3反弹必暴击且无视BOSS护盾减伤 | 棱镜矩阵/相位折叠';
        if (key === 'rift') return '锚弹'+_adjBase('rift', RIFT_BASE_DMG)+'/发 · 3锚生成裂界线(每条'+RIFT_LINE_DPS_PCT*100+'%/秒) | 坍缩'+RIFT_COLLAPSE_PCT*100+'%/线 | 锐化+35% | 共振×'+RIFT_RESONANCE_MULT;
        return `${_adjBase(key, cat.baseDmg)}${cat.unit}`;
    }
